#!/usr/bin/env bash
# ==============================================================================
# apply-my-settings.sh — restores personal macOS preferences.
# Generated by scripts/export-macos-settings.sh on 2026-11-08.
# Run: bash backups/apply-my-settings.sh
# ==============================================================================

echo "🚀 Applying macOS preferences..."

# Quit System Settings so it does not overwrite the new values
osascript -e 'tell application "System Settings" to quit' 2>/dev/null || true

echo "⚙️  Keyboard & text input"
defaults write -g "InitialKeyRepeat" -int 15
defaults write -g "KeyRepeat" -float 2
defaults write -g "ApplePressAndHoldEnabled" -bool false
defaults write -g "NSAutomaticSpellingCorrectionEnabled" -bool false
defaults write -g "NSAutomaticCapitalizationEnabled" -bool false
defaults write -g "NSAutomaticPeriodSubstitutionEnabled" -bool false
defaults write -g "NSAutomaticQuoteSubstitutionEnabled" -bool true
defaults write -g "NSAutomaticDashSubstitutionEnabled" -bool true

echo "⚙️  Trackpad gestures"
defaults write com.apple.AppleMultitouchTrackpad "Clicking" -bool true
defaults write com.apple.AppleMultitouchTrackpad "TrackpadThreeFingerDrag" -bool true
defaults write com.apple.AppleMultitouchTrackpad "TrackpadRightClick" -bool true
defaults write com.apple.AppleMultitouchTrackpad "TrackpadCornerSecondaryClick" -int 0
defaults write com.apple.AppleMultitouchTrackpad "TrackpadScroll" -bool true
defaults write com.apple.AppleMultitouchTrackpad "TrackpadPinch" -int 1
defaults write com.apple.AppleMultitouchTrackpad "TrackpadRotate" -int 1
defaults write com.apple.AppleMultitouchTrackpad "TrackpadTwoFingerDoubleTapGesture" -int 1
defaults write com.apple.AppleMultitouchTrackpad "TrackpadThreeFingerTapGesture" -int 0
defaults write com.apple.AppleMultitouchTrackpad "TrackpadThreeFingerHorizSwipeGesture" -int 0
defaults write com.apple.AppleMultitouchTrackpad "TrackpadThreeFingerVertSwipeGesture" -int 0
defaults write com.apple.AppleMultitouchTrackpad "TrackpadFourFingerHorizSwipeGesture" -int 2
defaults write com.apple.AppleMultitouchTrackpad "TrackpadFourFingerVertSwipeGesture" -int 2
defaults write com.apple.AppleMultitouchTrackpad "TrackpadFourFingerPinchGesture" -int 2
defaults write com.apple.AppleMultitouchTrackpad "TrackpadFiveFingerPinchGesture" -int 2

echo "⚙️  Bluetooth trackpad gestures"
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "Clicking" -bool true
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadThreeFingerDrag" -bool true
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadRightClick" -bool true
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadCornerSecondaryClick" -int 0
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadScroll" -bool true
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadPinch" -int 1
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadRotate" -int 1
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadTwoFingerDoubleTapGesture" -int 1
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadThreeFingerTapGesture" -int 0
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadThreeFingerHorizSwipeGesture" -int 0
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadThreeFingerVertSwipeGesture" -int 0
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadFourFingerHorizSwipeGesture" -int 2
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadFourFingerVertSwipeGesture" -int 2
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadFourFingerPinchGesture" -int 2
defaults write com.apple.driver.AppleBluetoothMultitouch.trackpad "TrackpadFiveFingerPinchGesture" -int 2

echo "⚙️  Pointer & scroll speed"
defaults write -g "com.apple.trackpad.scaling" -float 3
defaults write -g "com.apple.mouse.scaling" -float 3
defaults write -g "com.apple.scrollwheel.scaling" -float 1

echo "⚙️  Finder"
defaults write com.apple.finder "ShowPathbar" -bool true
defaults write com.apple.finder "ShowStatusBar" -bool true
defaults write com.apple.finder "_FXSortFoldersFirst" -bool true
defaults write com.apple.finder "FXPreferredViewStyle" -string "icnv"

echo "⚙️  File extensions"
defaults write NSGlobalDomain "AppleShowAllExtensions" -bool true

echo "⚙️  No .DS_Store on network/USB drives"
defaults write com.apple.desktopservices "DSDontWriteNetworkStores" -bool true
defaults write com.apple.desktopservices "DSDontWriteUSBStores" -bool true

echo "⚙️  Dock & Mission Control"
defaults write com.apple.dock "autohide" -bool false
defaults write com.apple.dock "tilesize" -float 37
defaults write com.apple.dock "largesize" -float 37
defaults write com.apple.dock "show-recents" -bool false

echo "🔄 Restarting Finder, Dock and SystemUIServer..."
killall Finder Dock SystemUIServer 2>/dev/null || true

echo "✅ Done. Some trackpad settings need a logout to take effect."
